contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 sendAmount, uint256 callValue, bytes calldata data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (sendAmount) + (callValue)); require(sendAmount <= 1000000000000000000000000000000); require(callValue <= 1000000000000000000000000000000);
        require(address(this).balance >= sendAmount, "insufficient balance for setup");
        require(address(this).balance >= callValue, "insufficient balance for call");
        c.Command{value: sendAmount}(address(this), data); if (__ESBMC_reverted()) return;
        uint256 pre = address(c).balance;
        bool reverted;
        c.Command{value: callValue}(address(this), data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        uint256 post = address(c).balance;
        assert(reverted || post + callValue >= pre);
    }

    receive() external payable {}
}

