pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX3 c;

    function setUp() public {
        c = new MultiplicatorX3();
    }

    function _run(uint256 sendAmount, uint256 callValue, bytes memory data) internal {
        sendAmount = bound(sendAmount, 0, 1000000000000000000000000000000);
        callValue = bound(callValue, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sendAmount);
        vm.assume(address(this).balance >= callValue);
        try c.Command{value: sendAmount}(address(this), data) {} catch { return; }
        uint256 pre = address(c).balance;
        bool reverted;
        try c.Command{value: callValue}(address(this), data) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 post = address(c).balance;
        assertTrue(reverted || post + callValue >= pre);
    }

    function testFuzz_run(uint256 sendAmount, uint256 callValue, bytes memory data) public {
        _run(sendAmount, callValue, data);
    }

    receive() external payable {}
}
